-- 9028_s4_mail_routes.sql -- S4 phase 2.3 follow-up (L-INT-2): the Owner sets where fetched statement mail is filed.
-- Expand-only. Not in the V1.2 register (D-MRT-1).
--   NEW: bnx.cmd_set_mail_route (Owner, PWA, tier 3): appends a route. kind 'institution' = messages from that institution's
--        verified sender domains go to folder_ref from effective_from (until effective_to); kind 'coverage_home' = the
--        mailbox's catch-all folder for verified statement mail without an institution route (mailbox must be the coverage home).
--        Routes are append-only (9010 table class E): a change is a newer route; bnx.mail_route_folder (9025) takes the latest
--        route in effect on the message's received date.
--   NEW: bnx.q_mail_routes (Owner, PWA): the routes of every mailbox, newest first; no address.
set role bnx_definer;

create function bnx.cmd_set_mail_route(cred jsonb, cmd jsonb) returns jsonb
language plpgsql security definer set search_path = pg_catalog, pg_temp as $$
declare a bnx.actor := bnx.resolve_actor(cred); rc jsonb; role text; k text := coalesce(cmd->>'kind', 'institution'); rid uuid;
        src bnx_intake.mail_source; frm date; til date;
begin
  role := bnx.require(a, 3);
  if role <> 'owner' then perform bnx.fail('FORBIDDEN_ROLE', 'P0403'); end if;
  if a.channel is distinct from 'pwa' then perform bnx.fail('FORBIDDEN_CHANNEL', 'P0403'); end if;
  rc := bnx.idem_begin(a, 'set_mail_route', cmd); if rc is not null then return rc; end if;
  select * into src from bnx_intake.mail_source where source_ref = cmd->>'source_ref';
  if not found then perform bnx.fail('NOT_FOUND', 'P0404', 'mail source'); end if;
  if coalesce(cmd->>'folder_ref', '') !~ '^[A-Za-z0-9_./-]{1,120}$' then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'folder_ref'); end if;
  begin frm := coalesce((cmd->>'effective_from')::date, current_date); til := (cmd->>'effective_to')::date;
  exception when others then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'effective dates'); end;
  if k = 'institution' then
    begin
      insert into bnx_intake.mail_folder_route(source_ref, institution_id, folder_ref, effective_from, effective_to, created_by)
      values (src.source_ref, (cmd->>'institution_id')::uuid, cmd->>'folder_ref', frm, til, a.member_id) returning id into rid;
    exception when foreign_key_violation or check_violation or not_null_violation or invalid_text_representation then
      perform bnx.fail('VALIDATION_FAILED', 'P0422', 'institution route');
    end;
  elsif k = 'coverage_home' then
    if not src.coverage_home then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'the mailbox is not the coverage home'); end if;
    insert into bnx_intake.mail_route_rule(source_ref, rule_kind, folder_ref, effective_from, created_by)
    values (src.source_ref, 'coverage_home', cmd->>'folder_ref', frm, a.member_id) returning id into rid;
  else
    perform bnx.fail('VALIDATION_FAILED', 'P0422', 'kind');
  end if;
  perform bnx.audit(a, 'set_mail_route', jsonb_build_object('route_id', rid, 'source_ref', src.source_ref), cmd, null);
  return bnx.idem_end(a, 'set_mail_route', cmd, jsonb_build_object('route_id', rid, 'kind', k, 'effective_from', frm));
end $$;

create function bnx.q_mail_routes(cred jsonb, q jsonb) returns jsonb
language plpgsql security definer set search_path = pg_catalog, pg_temp as $$
declare a bnx.actor := bnx.resolve_actor(cred); role text;
begin
  role := bnx.require(a, 3);
  if role <> 'owner' then perform bnx.fail('FORBIDDEN_ROLE', 'P0403'); end if;
  return jsonb_build_object('routes', coalesce((select jsonb_agg(x order by x->>'effective_from' desc, x->>'route_id') from (
      select jsonb_build_object('route_id', r.id, 'kind', 'institution', 'source_ref', r.source_ref, 'institution_id', r.institution_id,
               'institution', i.name_en, 'folder_ref', r.folder_ref, 'effective_from', r.effective_from, 'effective_to', r.effective_to) x
        from bnx_intake.mail_folder_route r left join bnx.institution i on i.id = r.institution_id
      union all
      select jsonb_build_object('route_id', u.id, 'kind', u.rule_kind, 'source_ref', u.source_ref, 'folder_ref', u.folder_ref,
               'effective_from', u.effective_from)
        from bnx_intake.mail_route_rule u) y), '[]'));
end $$;

